import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>抠掉背景的照片只完成了一半。透明抠图在使用之前，背后总得有点东西；一张普通的照片也常常需要一个合适的画框，才能放进要发布的地方。添加背景，就是把抠图变成成品图的那一步。</p>\n<p><a href=\"/zh/tupian-tianjia-beijing/\">给图片添加背景</a>工具可以把任意照片或透明 PNG 放到纯色、双色渐变，或者它自身的模糊版本上。整个过程都在浏览器里完成，你的图片不会离开自己的设备。</p>\n<p>这篇指南会讲三种背景模式、取景控制和导出选项，以及每种选择在什么时候最合适。不管你是卖产品、发社交媒体，还是做 Logo 设计，背景都是图片的一部分。</p>\n<h2 id=\"what-adding-a-background-means\">给图片添加背景是什么意思？</h2>\n<p>添加背景，就是把一张前景图放到一个新的背景上。前景可以是透明 PNG 抠图、产品照片、Logo 或截图。背景可以是纯色、渐变，或者照片自身的模糊版本。</p>\n<p>结果是一张前景和背景合在一起的成品图，可以保存为 JPG 或 PNG，用在任何能放普通图片的地方：网店商品页、社交帖子、演示文稿，或者网站横幅。</p>\n<p>这和抠图是两回事。抠图是把东西拿掉，添加背景是给前景搭建它所在的场景。这两个步骤常常成对出现：先抠掉杂乱的原始背景，再加一个适合用途的干净背景。</p>\n<p>这个工具本身不抠图。如果你的照片还带着原始背景，请先用背景抠图工具做出透明抠图，再拿到这里放到新背景上。</p>\n<h2 id=\"the-three-background-modes\">三种背景模式</h2>\n<p>纯色模式用一种单一的纯色填满画布。这是产品照片、Logo 和应用截图最干净的选择，因为没有任何东西会和前景抢注意力。白色是网店的标准色，品牌色则能把一张普通的抠图变成有品牌感的图片。</p>\n<p>渐变模式用两种颜色按你选择的角度在画布上过渡。它增加了纵深感，又不增加杂乱，适合社交帖子、故事封面和推广图片。柔和的渐变显得有设计感，强烈的渐变则可能压过安静的前景。</p>\n<p>模糊照片模式用前景图自身的模糊版本填满画布。这是解决照片与画框形状不匹配的经典办法：模糊的边缘填满空白区域，清晰的原图放在中间。因为颜色来自照片本身，看起来非常自然。</p>\n<p>每种模式都有自己的控制项。纯色模式有快捷色板和自定义取色器，渐变模式有两种颜色和一个角度，模糊照片模式有一个模糊半径。切换模式时前景和取景设置会保留，方便你快速比较几种效果。</p>\n<h2 id=\"solid-color-backgrounds\">纯色背景</h2>\n<p>当前景必须是画面里唯一被注意的东西时，纯色背景是最安全的选择。产品列表、头像和 Logo 展示都适合用纯色背景，因为它不会增加任何干扰。</p>\n<p>白色是电商的默认选择，因为各大平台都要求或偏好白色，也因为它能让产品看起来干净、诚实。白色背景在缩略图里也表现很好，杂乱的背景在小尺寸下会变成噪点，白色不会。</p>\n<p>品牌色适合用在推广活动而不是商品列表的场景里。品牌色方块上的抠图读起来像一张设计过的图片，一组相同颜色的图片放在一起，就形成了一个风格统一的信息流。颜色要全组保持一致，否则效果就散了。</p>\n<p>深色背景适合高端产品和氛围感强的照片。深色衬底能让浅色产品发光，营造出影棚的感觉。但要注意边缘：深色产品放在深色背景上，对比太低会被背景吞掉。</p>\n<h2 id=\"gradient-backgrounds\">渐变背景</h2>\n<p>渐变从一种颜色过渡到另一种颜色，角度控制决定了过渡的方向。对角渐变显得有动感，垂直渐变显得平静，水平渐变显得开阔。</p>\n<p>两种颜色接近的时候，渐变效果最好，比如两种蓝色，或者蓝色配青色。相近的颜色过渡平滑，看起来是特意设计的。色轮上对面的颜色容易冲突，只有在设计需要戏剧感时才适合用强对比。</p>\n<p>社交图片是渐变最自然的舞台。故事封面、语录卡片或推广帖子都能从渐变里获得能量，这是纯色给不了的。前景保持清晰，背景负责增加动感。</p>\n<p>前景细节丰富的时候，渐变要尽量柔和。细节多的产品照片配上大声的渐变，两边会抢注意力，最后吃亏的是产品。让渐变在细节多的前景后面安静待着，只在简单的前景后面才放开一点。</p>\n<h2 id=\"blurred-photo-backgrounds\">模糊照片背景</h2>\n<p>模糊照片模式解决的是画幅比例问题。竖构图的照片发成方形，左右会留出空白带；横构图的照片发成故事尺寸，上下会留出空白带。用照片自身的模糊版本填满这些空白，看起来是特意的，而不是空着的。</p>\n<p>模糊半径控制背景有多柔和。轻微模糊还能看清原图的形状，适合旅行和生活类照片。重度模糊会把背景融化成纯粹的色彩和质感，适合人像，因为脸必须占主导。</p>\n<p>这种模式会在模糊背景上加一层淡淡的色调，帮清晰的前景从它自己的模糊复制品里分离出来。没有这层色调，前景的边缘容易和背景融在一起，图片会失去层次。</p>\n<p>这种模式不只适用于抠图，任何照片都可以用。带着原始背景的完整照片也可以这样取景，模糊的复制品填满画框，清晰的原图放在中间。这是把照片改成另一种形状最快的方法。</p>\n<h2 id=\"canvas-aspect-ratios\">画布比例</h2>\n<p>画布比例决定成品图的最终形状。工具提供了常用形状的预设：方形适合信息流和商品页，16:9 适合宽屏，4:5 适合竖构图帖子。每个预设都对应图片要发布的地方。</p>\n<p>方形是最通用的形状。它能用在信息流、商品页和缩略图里，裁剪起来也可预测。不知道图片最终会用在哪里的时候，居中前景的方形画布是最安全的默认选择。</p>\n<p>16:9 的宽屏形状适合横幅、视频封面和网站头图。前景放在宽画布中间，读起来像一张主视觉图，两侧还能留出放文字的空间。但它不适合信息流帖子，到了信息流里会被缩成一条细带。</p>\n<p>4:5 的竖构图适合那些奖励高图片的社交信息流，因为高图片在用户滚动时占据更多屏幕空间。4:5 画布上配干净背景的产品，比同样产品放在方形画布上更能吸引注意力。</p>\n<h2 id=\"image-scale-and-margins\">图片缩放与留白</h2>\n<p>图片缩放控制前景在画布里显示得有多大。缩放得大，画面会被产品填满，产品成为主角。缩放得小，留白会比较宽裕，感觉平静、高级，像画廊里的展品。</p>\n<p>留白很重要，因为前景贴着边缘会显得拥挤，而漂浮在一大片背景里又会显得迷失。合适的缩放取决于前景本身：细节多的产品需要呼吸的空间，粗壮的 Logo 可以把画布填得更满。</p>\n<p>画布形状和照片形状不同的时候，缩放就成了取景工具。高照片放在方形画布上需要缩小才能放下，宽照片放在竖画布上也一样。缩放和比例是配合着工作的。</p>\n<p>在图片最终会被看到的尺寸下检查结果。网店列表里的缩略图只显示完整尺寸的一小部分，完整尺寸下看着宽裕的留白，在缩略图里可能显得空荡。导出之前，先缩小预览看一眼。</p>\n<h2 id=\"roundness-and-drop-shadow\">圆角与投影</h2>\n<p>圆角可以柔化前景图片的边角。长方形照片加了圆角，会有一种卡片的感觉，适合社交帖子和应用截图。透明 PNG 抠图的边角已经由图形本身决定，圆角对它作用不大。</p>\n<p>投影能让前景从背景上浮起来，增加纵深感，让抠图看起来是放上去的，而不是粘上去的。透明 Logo 和产品抠图用投影效果最好，因为阴影会跟着物体的形状走。</p>\n<p>纯色长方形照片加了投影，效果就像画框的影子：它描的是矩形的轮廓，而不是主体的轮廓。浅色背景上看着还行，深色背景上可能像一张漂浮的卡片。要根据实际的背景颜色来判断效果。</p>\n<p>这两个控制项都设计得很克制。投影太重或圆角太大，都会让注意力跑到特效上，而不是图片本身。加到刚好能增加纵深和质感就停下来，别让处理手法变成主角。</p>\n<h2 id=\"output-formats-and-quality\">输出格式与画质</h2>\n<p>工具可以把成品图导出为 JPG 或 PNG。JPG 适合照片，以及任何对文件大小有要求的图片，比如网站横幅或社交帖子。它压缩得好，加载得快。</p>\n<p>PNG 适合图片里有锐利文字和纯色色块、JPG 会把它压糊的情况。新背景盖满了整个画布，成品图里已经没有需要保留的透明度——PNG 在这里的价值是边缘清晰，而不是透明。PNG 文件更大，但每条边缘都保持清晰。</p>\n<p>JPG 的导出画质默认很高，能保留前景的细节和渐变的平滑。渐变背景用低画质导出会出现色带，也就是颜色之间能看到的阶梯。渐变背景一定要保持高画质。</p>\n<p>下载的文件名会反映背景设置，做了好几个版本时，能靠文件名区分它们。不用打开五张长得差不多的图，才能找到想要的那一张。</p>\n<h2 id=\"backgrounds-for-product-photos\">产品照片的背景</h2>\n<p>产品照片的成败取决于背景。干净的白色背景是各大平台的标准，因为它去掉了干扰，让买家公平地比较产品。它还和缩略图网格很搭，背景一致的店铺看起来更专业。</p>\n<p>彩色背景适合品牌店铺和社交卖场，在那里图片既是商品列表，也是广告。一组产品图用同一个品牌色，信息流就会变成一个一眼能认出的店面。但产品必须和背景有对比，否则会消失在背景里。</p>\n<p>生活场景是第三种选择，也就是把产品放进一个真实场景里展示，而不是放在纯色上。模糊照片背景可以暗示一个场景，不用真的搭建场景，模糊的色彩暗示了一个真实的地方，产品保持清晰。</p>\n<p>不管选哪种，整个产品系列要保持一致。一个商品用一种背景、另一个商品用另一种背景的店铺，看起来毫无章法；而一个背景系统用到底的店铺，看起来像一个品牌。一致性是最便宜的精致感。</p>\n<h2 id=\"backgrounds-for-social-media\">社交媒体的背景</h2>\n<p>社交信息流奖励那些能让手指停下来的图片，背景要承担一半的工作。大胆的渐变或强烈的品牌色，比普通的白色方块更快抓住眼球，所以推广帖子用彩色，商品列表用白色。</p>\n<p>画布形状要和平台匹配。方形适合信息流网格，竖构图 4:5 适合滚动的信息流，宽屏 16:9 适合故事链接或视频封面。形状错了，平台会按自己的方式裁剪，裁剪很少会照顾你的取景。</p>\n<p>给平台界面留出空间。大部分应用的说明文字、按钮和头像都会盖住图片的边缘，所以前景要居中，离边框远一点。贴着边缘的产品可能被按钮挡住。</p>\n<p>发布之前先在手机上测试图片。在桌面显示器上看着柔和的背景，在手机屏幕上可能显得很吵；在大的显示器上看着平滑的渐变，在小的屏幕上可能出现色带。手机才是观众真正看到它的地方。</p>\n<h2 id=\"common-mistakes\">常见错误</h2>\n<p>最常见的错误是背景和前景打架。细节丰富的产品配上大声的渐变，或者细 Logo 配上杂乱的模糊背景，都会分散注意力，削弱图片。背景应该衬托主体，永远不要和它竞争。</p>\n<p>另一个错误是忘了导出格式。透明抠图加了新背景，导出 JPG 完全没问题，因为背景已经填满了透明部分。但抠图导出 PNG，而 JPG 明明就够用的时候，只会白白浪费文件体积，看不到任何好处。</p>\n<p>第三个错误是不管最终的观看尺寸。完整尺寸下看着宽裕的留白，在缩略图里显得空荡；细节在图片缩小时会消失。导出之前，一定要在实际会被看到的尺寸下预览。</p>\n<p>最后，很多人会给一张还带着原始杂乱背景的照片加背景。工具会把整张照片放到新背景上，旧背景就还留在画框里面。先抠掉旧背景，再加新背景。</p>\n<h2 id=\"quick-reference\">快速参考：如何选择背景</h2>\n<p>商品列表、Logo，以及任何前景必须占主导的场景，用纯色。社交图片和推广用渐变，画面需要能量的时候它能帮上忙。画框形状和照片形状不一样、需要填补空隙时，用模糊照片。</p>\n<p>根据发布地点设置画布比例，前景缩放留出呼吸感，照片导出 JPG，锐利文字导出 PNG。在观众会看到的尺寸下预览一遍再发布。</p>\n<p>想看一步步的操作，请读<a href=\"/zh/blog/ruhe-gei-tupian-tianjia-beijing/\">如何给图片添加背景</a>；想看针对产品的建议，请读<a href=\"/zh/blog/shangpin-tupian-beijing-xuanze-zhinan/\">产品图背景怎么选：颜色、场景与平台规则</a>。现在就用<a href=\"/zh/tupian-tianjia-beijing/\">给图片添加背景</a>工具试试，或者先用<a href=\"/zh/quchu-beijing/\">背景抠图</a>工具做出干净的抠图。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"添加背景和抠掉背景有什么区别？","answer":"抠掉背景是把旧背景拿掉，留下一张透明抠图。添加背景是把抠图或任意照片放到新背景上，比如纯色、渐变或模糊照片。这两个步骤常常成对出现。"},{"question":"产品照片应该选哪种背景模式？","answer":"纯白背景是各大平台的标准，因为它让产品成为唯一的焦点。自己的店铺或社交账号可以用一致的品牌色，模糊照片背景则适合需要场景感的生活类照片。"},{"question":"可以给还带着原始背景的照片加背景吗？","answer":"可以，工具会把整张照片放到新背景上，但原始背景还会留在画框里面看得见。想要干净的效果，先用背景抠图工具抠掉旧背景，再把透明抠图放到新背景上。"},{"question":"加完背景应该导出 JPG 还是 PNG？","answer":"照片和任何对文件大小有要求的图片，比如社交帖子和网站横幅，用 JPG。图片里有锐利文字或纯色色块、需要保持边缘清晰时，用 PNG。新背景合成之后，已经没有需要保留的透明度，整个画布都被填满了。"},{"question":"为什么我的渐变背景会出现明显的色带？","answer":"渐变用低画质保存时会出现色带，因为 JPG 压缩会把相近的颜色归成能看到的阶梯。用高画质导出能让渐变保持平滑，大面积纯色渐变的图形最好直接用 PNG。"},{"question":"添加背景会改动我的原始照片文件吗？","answer":"不会。工具会生成一张前景和背景合在一起的新图片，原始文件在你的设备上保持原样。你可以用同一次上传，导出好几个不同背景的版本。"}];
